-- Verified target baseline corresponding to PostgreSQL migrations 001 through 010.
-- Timestamps are canonical UTC ISO-8601 strings generated by application code.

CREATE TABLE events (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL CHECK (length(name) <= 255),
  description TEXT,
  date TEXT NOT NULL CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  operator_name TEXT NOT NULL CHECK (length(operator_name) <= 255),
  created_at TEXT NOT NULL,
  UNIQUE (name, date)
) STRICT;

CREATE TABLE templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE CHECK (length(name) <= 255),
  type TEXT NOT NULL DEFAULT 'photo_strip' CHECK (type IN ('photo_strip', 'flipbook')),
  orientation TEXT NOT NULL CHECK (orientation IN ('landscape', 'portrait')),
  output_width INTEGER NOT NULL,
  output_height INTEGER NOT NULL,
  background_path TEXT,
  cover_path TEXT,
  background_x REAL NOT NULL DEFAULT 0,
  background_y REAL NOT NULL DEFAULT 0,
  background_width REAL NOT NULL DEFAULT 1800,
  background_height REAL NOT NULL DEFAULT 1200,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  required_capture_count INTEGER NOT NULL DEFAULT 3,
  countdown_seconds INTEGER NOT NULL DEFAULT 5 CHECK (countdown_seconds IN (3, 5, 10)),
  sort_order INTEGER,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) STRICT;

CREATE TABLE frames (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL CHECK (length(name) <= 255),
  overlay_path TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) STRICT;

CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  token TEXT NOT NULL CHECK (length(token) <= 64),
  event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  type TEXT NOT NULL CHECK (type IN ('photo_strip', 'flipbook')),
  state TEXT NOT NULL,
  template_id TEXT REFERENCES templates(id) ON DELETE SET NULL,
  frame_id TEXT REFERENCES frames(id) ON DELETE SET NULL,
  template_snapshot TEXT CHECK (template_snapshot IS NULL OR json_valid(template_snapshot)),
  retake_count INTEGER NOT NULL DEFAULT 0,
  is_printed INTEGER NOT NULL DEFAULT 0 CHECK (is_printed IN (0, 1)),
  copies_printed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  last_activity_at TEXT NOT NULL,
  cancelled_at TEXT
) STRICT;

CREATE TABLE session_captures (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  capture_index INTEGER NOT NULL,
  file_path TEXT NOT NULL,
  is_cover INTEGER NOT NULL DEFAULT 0 CHECK (is_cover IN (0, 1)),
  is_selected INTEGER NOT NULL DEFAULT 1 CHECK (is_selected IN (0, 1)),
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE session_videos (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  video_index INTEGER NOT NULL,
  file_path TEXT NOT NULL,
  duration_seconds REAL NOT NULL DEFAULT 6,
  is_selected INTEGER NOT NULL DEFAULT 0 CHECK (is_selected IN (0, 1)),
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE generated_outputs (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  public_id TEXT NOT NULL UNIQUE CHECK (length(public_id) = 7),
  media_type TEXT NOT NULL CHECK (media_type IN ('image/png', 'image/gif')),
  file_path TEXT NOT NULL,
  width INTEGER NOT NULL,
  height INTEGER NOT NULL,
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE publication_records (
  id TEXT PRIMARY KEY,
  output_id TEXT NOT NULL REFERENCES generated_outputs(id) ON DELETE CASCADE,
  public_id TEXT NOT NULL UNIQUE CHECK (length(public_id) = 7),
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'in_progress', 'uploaded', 'failed')),
  retry_count INTEGER NOT NULL DEFAULT 0,
  last_attempt_at TEXT,
  next_attempt_at TEXT,
  last_error TEXT,
  cloudinary_url TEXT,
  cloudinary_public_id TEXT,
  cloud_finalized_at TEXT,
  expires_at TEXT,
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE template_placements (
  id TEXT PRIMARY KEY,
  template_id TEXT NOT NULL REFERENCES templates(id) ON DELETE CASCADE,
  capture_index INTEGER NOT NULL CHECK (capture_index >= 1),
  x REAL NOT NULL,
  y REAL NOT NULL,
  width REAL NOT NULL CHECK (width > 0),
  height REAL NOT NULL CHECK (height > 0),
  rotation REAL NOT NULL DEFAULT 0,
  border_radius REAL NOT NULL DEFAULT 0 CHECK (border_radius >= 0),
  z_index INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE template_overlays (
  id TEXT PRIMARY KEY,
  template_id TEXT NOT NULL REFERENCES templates(id) ON DELETE CASCADE,
  label TEXT NOT NULL CHECK (length(label) <= 255),
  asset_path TEXT,
  x REAL NOT NULL DEFAULT 0,
  y REAL NOT NULL DEFAULT 0,
  width REAL NOT NULL CHECK (width > 0),
  height REAL NOT NULL CHECK (height > 0),
  rotation REAL NOT NULL DEFAULT 0,
  z_index INTEGER NOT NULL DEFAULT 2,
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE print_jobs (
  id TEXT PRIMARY KEY,
  output_id TEXT REFERENCES generated_outputs(id) ON DELETE SET NULL,
  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  request_key TEXT NOT NULL UNIQUE,
  artifact_path TEXT NOT NULL,
  artifact_type TEXT NOT NULL CHECK (artifact_type IN ('image/png', 'application/pdf')),
  public_id TEXT NOT NULL CHECK (length(public_id) = 7),
  output_type TEXT NOT NULL CHECK (output_type IN ('photo_strip', 'flipbook')),
  printer_name TEXT NOT NULL,
  media_size TEXT NOT NULL,
  copies_requested INTEGER NOT NULL CHECK (copies_requested BETWEEN 1 AND 10),
  copies_completed INTEGER NOT NULL DEFAULT 0 CHECK (copies_completed >= 0),
  mode TEXT NOT NULL CHECK (mode IN ('cups', 'simulation')),
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'submitting', 'pending', 'processing', 'stopped', 'completed', 'failed', 'canceled', 'needs_attention')),
  last_error TEXT,
  last_reconciled_at TEXT,
  reprint_of_id TEXT REFERENCES print_jobs(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) STRICT;

CREATE TABLE print_job_attempts (
  id TEXT PRIMARY KEY,
  print_job_id TEXT NOT NULL REFERENCES print_jobs(id) ON DELETE CASCADE,
  attempt_number INTEGER NOT NULL,
  title TEXT NOT NULL,
  cups_job_id TEXT,
  state TEXT NOT NULL DEFAULT 'submitting',
  error TEXT,
  is_current INTEGER NOT NULL DEFAULT 1 CHECK (is_current IN (0, 1)),
  superseded_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (print_job_id, attempt_number)
) STRICT;

CREATE INDEX idx_sessions_event_id ON sessions(event_id);
CREATE INDEX idx_sessions_token ON sessions(token);
CREATE INDEX idx_generated_outputs_public_id ON generated_outputs(public_id);
CREATE INDEX idx_publication_records_status ON publication_records(status);
CREATE INDEX idx_publication_records_public_id ON publication_records(public_id);
CREATE INDEX idx_publication_records_due ON publication_records(status, next_attempt_at) WHERE status = 'queued';
CREATE INDEX idx_template_placements_template_id ON template_placements(template_id);
CREATE INDEX idx_template_overlays_template_id ON template_overlays(template_id);
CREATE INDEX idx_print_jobs_status_created ON print_jobs(status, created_at DESC);
CREATE INDEX idx_print_jobs_output_active ON print_jobs(output_id) WHERE status IN ('queued', 'submitting', 'pending', 'processing', 'stopped');
CREATE INDEX idx_print_job_attempts_job ON print_job_attempts(print_job_id, attempt_number DESC);
CREATE UNIQUE INDEX idx_print_job_attempts_one_current ON print_job_attempts(print_job_id) WHERE is_current = 1;
CREATE INDEX idx_print_job_attempts_superseded_reconciliation ON print_job_attempts(is_current, state) WHERE cups_job_id IS NOT NULL;
